"""Train the Network Watch domain model: is this domain machine-generated by malware (DGA)?

Data (downloaded by data/public/download.sh into data/public/raw/, never committed):
  dga_domains_full.csv  Cucchiarelli et al. 2021 (ESWA 170:114551): 25 DGA families from the
                        Netlab 360 open data feed (13,500 each) + 337,398 Alexa domains.
                        Research use; cite the paper.
  top-100000-domains    an independent popular-domain list, used ONLY as an extra false-alarm test.

Splits (no tuning on test):
  * 6 whole families are held out of training entirely ("unseen families"), including the two
    dictionary-word DGAs (suppobox, matsnu) that are the hardest kind;
  * the 19 training families and the Alexa domains are split 80/10/10 by registrable domain hash;
  * the threshold is picked on the validation split for <= 0.5% false alarms.
Outputs assets/models/domain_model.{bin,json} and bench/results/netwatch_domain.json.
"""
from __future__ import annotations

import csv
import json
import sys
import zlib
from pathlib import Path

import numpy as np
from sklearn.linear_model import LogisticRegression

ROOT = Path(__file__).resolve().parents[2]
sys.path.insert(0, str(ROOT))
from kavach_core.features import LinearModel  # noqa: E402
from kavach_core.netwatch import domain_core, domain_matrix  # noqa: E402

RAW = ROOT / "data/public/raw"
DIM = 1 << 16
HELDOUT_FAMILIES = ["suppobox", "matsnu", "gozi", "cryptolocker", "necurs", "pushdo"]
TARGET_FPR = 0.005


def bucket(host: str) -> int:
    core, tld = domain_core(host)
    return zlib.crc32((".".join(core[-1:]) + "." + tld).encode()) % 10


def main() -> None:
    rows = list(csv.reader(open(RAW / "dga_domains_full.csv", encoding="utf-8", errors="ignore")))
    data = {"train": [], "val": [], "test": [], "unseen": []}
    for cls, fam, host in rows:
        host = host.strip().lower()
        if not host:
            continue
        y = 1 if cls == "dga" else 0
        if y and fam in HELDOUT_FAMILIES:
            data["unseen"].append((host, y, fam))
            continue
        b = bucket(host)
        data["train" if b < 8 else "val" if b == 8 else "test"].append((host, y, fam))
    # Indian genuine domains must never be flagged: add to train benign
    genuine = json.loads((ROOT / "assets/genuine_domains.json").read_text(encoding="utf-8"))
    gdoms = [d for d in genuine["domains"] if "." in d]
    data["train"] += [(d, 0, "genuine_in") for d in gdoms]
    for k, v in data.items():
        print(k, len(v), "pos", sum(y for _, y, _ in v))

    Xtr = domain_matrix([h for h, _, _ in data["train"]], DIM)
    ytr = np.array([y for _, y, _ in data["train"]])
    clf = LogisticRegression(C=4.0, max_iter=2000, solver="liblinear")
    clf.fit(Xtr, ytr)

    def scores(split):
        X = domain_matrix([h for h, _, _ in data[split]], DIM)
        return clf.decision_function(X)

    sv = scores("val")
    yv = np.array([y for _, y, _ in data["val"]])
    neg = np.sort(sv[yv == 0])
    thr_logit = float(neg[int(len(neg) * (1 - TARGET_FPR))])
    thr = float(1 / (1 + np.exp(-thr_logit)))

    res = {"threshold": thr, "target_val_fpr": TARGET_FPR, "heldout_families": HELDOUT_FAMILIES, "splits": {}}
    for split in ["val", "test", "unseen"]:
        s = scores(split)
        y = np.array([yy for _, yy, _ in data[split]])
        fams = [f for _, _, f in data[split]]
        pred = s >= thr_logit
        r = {"n": int(len(y))}
        if (y == 0).any():
            r["false_alarm_rate"] = round(float(pred[y == 0].mean()), 4)
        if (y == 1).any():
            r["recall"] = round(float(pred[y == 1].mean()), 4)
        per = {}
        for f in sorted(set(fams)):
            m = np.array([ff == f for ff in fams]) & (y == 1)
            if m.any():
                per[f] = round(float(pred[m].mean()), 4)
        r["recall_by_family"] = per
        res["splits"][split] = r
    # independent false-alarm test: popular domains not in the training data
    seen = {h for h, _, _ in data["train"]}
    top = [l.strip().lower() for l in open(RAW / "top-100000-domains", encoding="utf-8") if l.strip()]
    top = [h for h in top if h not in seen]
    st = clf.decision_function(domain_matrix(top, DIM))
    res["top100k_false_alarm_rate"] = round(float((st >= thr_logit).mean()), 4)
    res["top100k_n"] = len(top)
    res["top100k_false_alarm_examples"] = [top[i] for i in np.argsort(-st)[:15]]
    gs = clf.decision_function(domain_matrix(gdoms, DIM)) if gdoms else np.array([])
    res["genuine_in_flagged"] = [d for d, v in zip(gdoms, gs) if v >= thr_logit]
    print(json.dumps(res, indent=1))

    w = np.zeros(DIM, dtype=np.float32)
    w[:] = clf.coef_[0]
    LinearModel("domain_model", DIM, w, float(clf.intercept_[0]), thr,
                {"task": "dga-domain", "tokens": "kavach_core.netwatch.domain_tokens", "trained_on": "dga_domains_full.csv (19 families) + Alexa"}
                ).save(ROOT / "assets/models")
    (ROOT / "bench/results/netwatch_domain.json").write_text(json.dumps(res, indent=1), encoding="utf-8")


if __name__ == "__main__":
    main()
